import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Pedoman Etika Antar Bidang","description":"","frontmatter":{},"headers":[],"relativePath":"id/88-跨位面伦理准则.md","filePath":"id/88-跨位面伦理准则.md","lastUpdated":null}'),r={name:"id/88-跨位面伦理准则.md"};function k(d,a,s,u,m,p){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="pedoman-etika-antar-bidang" tabindex="-1">Pedoman Etika Antar Bidang <a class="header-anchor" href="#pedoman-etika-antar-bidang" aria-label="Permalink to &quot;Pedoman Etika Antar Bidang&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>88</td></tr><tr><td>Modul</td><td>Interaksi Antar Bidang dan Aturan Waktu</td></tr><tr><td>Kata Kunci Inti</td><td>Etika antar bidang, otonomi peradaban, non-intervensi, penghormatan budaya, diplomasi simbiosis</td></tr></tbody></table><h2 id="_1-dasar-filosofis-pedoman-etika" tabindex="-1">1. Dasar Filosofis Pedoman Etika <a class="header-anchor" href="#_1-dasar-filosofis-pedoman-etika" aria-label="Permalink to &quot;1. Dasar Filosofis Pedoman Etika&quot;">​</a></h2><p>Pedoman etika antar bidang adalah norma moral dan kode etik yang harus diikuti oleh peradaban simbiosis neo saat berinteraksi dengan peradaban bidang lainnya. Dasar filosofisnya adalah prinsip &quot;subjektivitas peradaban&quot; — setiap peradaban bidang, terlepas dari tingkat perkembangannya, bentuk rasnya, atau sistem sosialnya, memiliki subjektivitas yang tidak dapat dicabut dan hak atas perkembangan otonom. Peradaban asing mana pun tidak boleh dengan alasan apa pun mencabut subjektivitas ini, atau memaksakan kehendaknya sendiri kepada peradaban lainnya.</p><p>Penetapan dasar filosofis ini sejalan dengan ide inti &quot;anti-predator&quot; dari peradaban simbiosis neo. Ciri khas peradaban predator adalah tidak mengakui subjektivitas peradaban lain, dan memperlakukan peradaban lain sebagai sumber daya yang dapat dimanfaatkan atau objek yang dapat ditaklukkan. Agar peradaban simbiosis neo benar-benar melampaui peradaban predator, ia harus sepenuhnya meninggalkan mentalitas ini dalam interaksi antar bidang, dan memperlakukan setiap peradaban yang ditemui dengan sikap kesetaraan, penghormatan, dan simbiosis.</p><p>Ruang lingkup efektivitas pedoman etika antar bidang mencakup semua perilaku interaksi antar bidang, termasuk namun tidak terbatas pada: penyeberangan bidang, komunikasi antar bidang, kegiatan arkeologi, perdagangan, pertukaran budaya, kerja sama teknis, dan intervensi kemanusiaan dalam situasi darurat. Setiap organisasi dan individu saat melakukan interaksi antar bidang harus mematuhi semua ketentuan pedoman ini.</p><h2 id="_2-enam-prinsip-etika" tabindex="-1">2. Enam Prinsip Etika <a class="header-anchor" href="#_2-enam-prinsip-etika" aria-label="Permalink to &quot;2. Enam Prinsip Etika&quot;">​</a></h2><p>Pedoman etika antar bidang terdiri dari enam prinsip dasar, yang membentuk sistem nilai etika yang lengkap:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Inti Konten</th><th>Persyaratan Spesifik</th></tr></thead><tbody><tr><td>Prinsip Otonomi Peradaban</td><td>Menghormati hak perkembangan otonom peradaban bidang target, tidak mencampuri urusan internalnya secara paksa</td><td>Tidak boleh memaksa mengubah sistem sosial, ideologi, dan jalan perkembangan peradaban target; tidak boleh menumbuhkan agen atau rezim boneka di dalam peradaban target</td></tr><tr><td>Prinsip Non-Intervensi</td><td>Kecuali jika peradaban target menghadapi krisis tingkat kepunahan dan secara aktif meminta bantuan, jika tidak maka tidak melakukan intervensi substansial apa pun</td><td>Tidak boleh campur tangan dalam konflik internal peradaban target; tidak boleh memberikan senjata atau bantuan militer kepada pihak mana pun dari peradaban target; tidak boleh memanipulasi opini publik dan proses politik peradaban target</td></tr><tr><td>Prinsip Penghormatan Budaya</td><td>Menghormati tradisi budaya, keyakinan agama, dan adat istiadat peradaban target</td><td>Tidak boleh melakukan penilaian diskriminatif atau ejekan jahat terhadap budaya peradaban target; tidak boleh memaksakan produk budaya dan nilai-nilai bidang自己; tidak boleh melakukan asimilasi budaya atas nama &quot;peradaban&quot;</td></tr><tr><td>Prinsip Kesetaraan dan Saling Menguntungkan</td><td>Interaksi antar bidang harus didasarkan pada kesetaraan, memastikan kedua belah pihak dapat memperoleh manfaat dari interaksi</td><td>Tidak boleh menggunakan keunggulan teknis untuk melakukan perdagangan yang tidak setara; tidak boleh menjarah sumber daya peradaban target; ekspor teknologi harus mempertimbangkan kemampuan penerimaan dan dampak sosial peradaban target</td></tr><tr><td>Prinsip Dampak Minimal</td><td>Interaksi antar bidang harus semaksimal mungkin mengurangi dampak eksternal terhadap peradaban target</td><td>Mengutamakan metode interaksi dengan kontak rendah dan gangguan rendah; ruang lingkup dan intensitas kegiatan interaksi harus dikendalikan secara ketat dalam batas yang diperlukan; setelah interaksi selesai, harus mengevaluasi dan menghilangkan dampak sisa yang tidak perlu</td></tr><tr><td>Prinsip Akuntabilitas</td><td>Semua perilaku interaksi antar bidang harus dapat dilacak, diawasi, dan dipertanggungjawabkan</td><td>Membangun arsip dan log interaksi yang lengkap; mendirikan lembaga pengawasan etika independen; melakukan penyelidikan dan hukuman terhadap perilaku yang melanggar pedoman etika</td></tr></tbody></table><p>Terdapat hubungan logis intrinsik di antara enam prinsip: prinsip otonomi peradaban adalah nilai fundamental, prinsip non-intervensi adalah persyaratan inti, prinsip penghormatan budaya adalah perwujudan di tingkat budaya, prinsip kesetaraan dan saling menguntungkan adalah jaminan di tingkat ekonomi, prinsip dampak minimal adalah norma di tingkat operasional, dan prinsip akuntabilitas adalah batasan di tingkat institusional. Keenamnya bersama-sama membentuk siklus etika lengkap &quot;nilai—persyaratan—perwujudan—jaminan—norma—batasan&quot;.</p><h2 id="_3-norma-etika-untuk-berbagai-skenario-interaksi" tabindex="-1">3. Norma Etika untuk Berbagai Skenario Interaksi <a class="header-anchor" href="#_3-norma-etika-untuk-berbagai-skenario-interaksi" aria-label="Permalink to &quot;3. Norma Etika untuk Berbagai Skenario Interaksi&quot;">​</a></h2><h3 id="_3-1-norma-etika-untuk-skenario-arkeologi" tabindex="-1">3.1 Norma Etika untuk Skenario Arkeologi <a class="header-anchor" href="#_3-1-norma-etika-untuk-skenario-arkeologi" aria-label="Permalink to &quot;3.1 Norma Etika untuk Skenario Arkeologi&quot;">​</a></h3><p>Arkeologi antar bidang adalah salah satu skenario interaksi yang paling umum, dan inti dari norma etikanya adalah &quot;tidak mengganggu&quot;. Tim arkeologi harus secara ketat mengikuti skema standar cermin salinan + ruang terisolasi + hanya mengembalikan pengetahuan, memastikan proses arkeologi tidak dirasakan oleh peradaban target. Untuk bidang yang masih memiliki peradaban hidup, ruang lingkup arkeologi harus dibatasi secara ketat pada area reruntuhan yang telah ditinggalkan, dan tidak boleh melakukan pemindaian atau penyalinan dalam bentuk apa pun terhadap area pemukiman peradaban hidup.</p><p>Pengetahuan temuan arkeologi saat dikembalikan dan dipublikasikan harus menghormati sensitivitas budaya peradaban target. Jika temuan arkeologi melibatkan benda suci agama, sisa-sisa leluhur, atau tabu budaya peradaban target, informasi terkait harus经过 pemeriksaan sensitivitas budaya dari Komite Etika Antar Bidang sebelum dipublikasikan, dan jika perlu melakukan proses pengaburan terhadap detail sensitif.</p><h3 id="_3-2-norma-etika-untuk-skenario-komunikasi" tabindex="-1">3.2 Norma Etika untuk Skenario Komunikasi <a class="header-anchor" href="#_3-2-norma-etika-untuk-skenario-komunikasi" aria-label="Permalink to &quot;3.2 Norma Etika untuk Skenario Komunikasi&quot;">​</a></h3><p>Komunikasi antar bidang adalah cara pertukaran langsung dengan peradaban target, dan inti dari norma etikanya adalah &quot;ketulusan dan penghormatan&quot;. Konten komunikasi harus benar, tidak boleh sengaja memberikan informasi palsu atau melakukan propaganda penipuan; nada komunikasi harus setara, tidak boleh bersikap merendahkan terhadap peradaban dengan tingkat perkembangan yang lebih rendah; tema komunikasi harus经过 persetujuan peradaban target, tidak boleh secara paksa mengirimkan ideologi atau keyakinan agama bidang自己.</p><p>Saat pertama kali membangun komunikasi dengan peradaban yang tidak dikenal, harus mengikuti norma &quot;kontak progresif&quot;: pertama-tama mengirimkan sinyal matematika dan fisika netral untuk mengonfirmasi tingkat kecerdasan dan kemampuan komunikasi pihak lain, kemudian secara bertahap memperluas ruang lingkup pertukaran berdasarkan respons pihak lain, dan tidak boleh mengirimkan informasi budaya atau teknis yang kompleks pada kontak pertama.</p><h3 id="_3-3-norma-etika-untuk-skenario-perdagangan" tabindex="-1">3.3 Norma Etika untuk Skenario Perdagangan <a class="header-anchor" href="#_3-3-norma-etika-untuk-skenario-perdagangan" aria-label="Permalink to &quot;3.3 Norma Etika untuk Skenario Perdagangan&quot;">​</a></h3><p>Inti dari norma etika perdagangan antar bidang adalah &quot;keadilan dan keberlanjutan&quot;. Perdagangan harus didasarkan pada kesukarelaan kedua belah pihak, tidak boleh menggunakan asimetri informasi atau keunggulan teknis untuk melakukan transaksi paksaan; harga perdagangan harus adil, tidak boleh melakukan penetapan harga predator; barang perdagangan tidak boleh mengandung konten yang dapat menyebabkan guncangan sosial atau kerusakan ekologis terhadap peradaban target.</p><p>Yang perlu diperhatikan secara khusus adalah bahwa perdagangan antar bidang untuk teknologi kultivasi dan senjata energi tinggi tunduk pada batasan etika yang paling ketat. Mengekspor teknologi kultivasi tingkat tinggi ke peradaban dengan tingkat perkembangan yang lebih rendah dapat menyebabkan ketidakseimbangan struktur sosial dan memperburuk konflik internal; mengekspor senjata dapat secara langsung memicu perang. Oleh karena itu, kedua jenis perdagangan ini pada prinsipnya dilarang, dan hanya dapat dilakukan dalam situasi yang sangat khusus setelah经过 persetujuan rapat pleno Dewan Neo.</p><h3 id="_3-4-norma-etika-untuk-skenario-intervensi-darurat" tabindex="-1">3.4 Norma Etika untuk Skenario Intervensi Darurat <a class="header-anchor" href="#_3-4-norma-etika-untuk-skenario-intervensi-darurat" aria-label="Permalink to &quot;3.4 Norma Etika untuk Skenario Intervensi Darurat&quot;">​</a></h3><p>Ketika peradaban bidang target menghadapi krisis tingkat kepunahan (seperti tabrakan asteroid, wabah super, keruntuhan hukum), peradaban simbiosis neo dapat melakukan intervensi kemanusiaan. Namun bahkan dalam situasi darurat seperti ini, norma etika berikut harus diikuti:</p><ul><li>Sebelum intervensi, harus获得 persetujuan terinformasi dari peradaban target semaksimal mungkin; jika peradaban target tidak dapat memberikan respons yang efektif karena krisis, maka Komite Etika Antar Bidang akan membuat penilaian &quot;persetujuan yang diasumsikan&quot; atas namanya</li><li>Sarana intervensi harus memilih skema dengan dampak minimal terhadap peradaban target, dan mengutamakan intervensi tidak langsung (seperti mengubah orbit asteroid) daripada intervensi langsung (seperti turun langsung untuk menyelamatkan)</li><li>Selama proses intervensi, tidak boleh mengambil kesempatan untuk获得 sumber daya atau teknologi peradaban target</li><li>Setelah intervensi selesai, harus segera mundur, dan tidak boleh meninggalkan keberadaan permanen di bidang target</li><li>Setelahnya, harus menyerahkan laporan intervensi lengkap kepada Komite Etika Antar Bidang, dan接受 pemeriksaan etika</li></ul><h2 id="_4-pengawasan-etika-dan-penanganan-pelanggaran" tabindex="-1">4. Pengawasan Etika dan Penanganan Pelanggaran <a class="header-anchor" href="#_4-pengawasan-etika-dan-penanganan-pelanggaran" aria-label="Permalink to &quot;4. Pengawasan Etika dan Penanganan Pelanggaran&quot;">​</a></h2><p>Hengyuanzhou mendirikan &quot;Komite Etika Antar Bidang&quot; sebagai lembaga pengawasan etika independen, yang bertanggung jawab untuk merumuskan dan menafsirkan pedoman etika antar bidang, menyetujui proyek interaksi antar bidang berisiko tinggi, menerima keluhan pelanggaran etika, serta melakukan penyelidikan dan keputusan terhadap perilaku pelanggaran. Komite ini terdiri dari ahli etika, ahli hukum, ilmuwan, dan perwakilan peradaban dari berbagai ras dan latar belakang profesional, memastikan keragaman dan ketidakberpihakan pengambilan keputusan.</p><p>Perilaku yang melanggar pedoman etika antar bidang, sesuai dengan tingkat keparahan situasi, tindakan penanganannya meliputi: peringatan lisan, kecaman tertulis, penangguhan kualifikasi interaksi antar bidang, pencabutan izin penyeberangan, denda, hukuman penjara, dan dalam situasi ekstrem &quot;pengasingan bidang&quot; (pencabutan hak tinggal di bidang utama Hengyuanzhou). Semua hasil penanganan pelanggaran etika dicatat dalam arsip etika individu atau organisasi, dan disimpan secara permanen.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Pedoman etika antar bidang adalah perwujudan terkonsentrasi dari ketinggian moral peradaban simbiosis neo. Pedoman ini tidak hanya mengatur &quot;apa yang tidak boleh dilakukan&quot;, tetapi yang lebih penting, ia menyatakan &quot;apa yang seharusnya menjadi&quot; — sebuah peradaban yang benar-benar besar bukanlah yang telah menaklukkan berapa banyak peradaban lain, melainkan yang telah menghormati subjektivitas berapa banyak peradaban lain. Di jalan Hengyuanzhou menuju simbiosis antarbintang, pedoman etika antar bidang akan selalu menjadi mercusuar moral yang mengarahkan arah.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>81-Aturan Penyeberangan Bidang</li><li>87-Prinsip Hanya Mengembalikan Pengetahuan</li><li>04-Garis Besar Inti Anti-Predator</li></ul>',30)])])}const l=n(r,[["render",k]]);export{o as __pageData,l as default};
